/**
 * A metric over a date range with a drill-down. The overview reads one governed metric grouped by
 * a dimension and draws it as a bar chart; clicking a bar opens the records view with the group and
 * the range in the URL, so the drill-down is a link the viewer can share. The provenance footer
 * cites the metric.
 *
 * Budget: every `Chart*` primitive shares one engine (recharts), so mixing chart types adds no second engine to the 2 MiB bundle cap.
 */
import { createRoot } from 'react-dom/client';
import {
  ChartBar,
  DateRangePicker,
  ProvenanceFooter,
  Section,
  SurfaceApp,
  parseAsIsoDate,
  parseAsString,
  useMetric,
  useNavigation,
  useQuery,
  useQueryState,
  useSurfaceApp,
} from '@cynap/surface-sdk';

import './styles.css';

/** The metric, the dimension it is grouped by, and the entity type behind it. Replace all three. */
const METRIC_NAME = 'REPLACE_WITH_METRIC_NAME';
const GROUP_BY = 'REPLACE_WITH_DIMENSION';
const ENTITY_TYPE = 'REPLACE_WITH_ENTITY_TYPE';
/** The portal path of this Surface's landing route: `/data/` plus its `path` in routes.json. */
const MOUNT_PATH = '/data/replace-with-landing-path';

type Row = Record<string, unknown>;
const isRecord = (value: unknown): value is Row => typeof value === 'object' && value !== null && !Array.isArray(value);
/**
 * A grouped metric row is `{label, value}`: the group's value is `label`, never a key named after
 * the dimension. A metric grouped by two dimensions labels each row `"<a> / <b>"`.
 */
const labelOf = (row: Row) => String(row.label ?? '');
const valueOf = (row: Row) => (typeof row.value === 'number' ? row.value : Number(row.value) || 0);

function useRange() {
  const [from, setFrom] = useQueryState('from', parseAsIsoDate);
  const [to, setTo] = useQueryState('to', parseAsIsoDate);
  return { from, to, setFrom, setTo };
}

/** `YYYY-MM-DD` ↔ a UTC midnight `Date`, for the picker. */
const toDate = (day: string | null) => (day ? new Date(`${day}T00:00:00Z`) : undefined);
const toDay = (date: Date | undefined) => (date ? date.toISOString().slice(0, 10) : null);

function Overview() {
  const { navigate } = useNavigation();
  const range = useRange();
  const metric = useMetric(METRIC_NAME, {
    group_by: GROUP_BY,
    ...(range.from ? { date_from: range.from } : {}),
    ...(range.to ? { date_to: range.to } : {}),
  });

  function drill(group: string) {
    const query = new URLSearchParams({ group });
    if (range.from) query.set('from', range.from);
    if (range.to) query.set('to', range.to);
    navigate(`${MOUNT_PATH}/records?${query.toString()}`);
  }

  return (
    <main className="tpl-page">
      <DateRangePicker
        value={{ from: toDate(range.from), to: toDate(range.to) }}
        onChange={(next) => {
          range.setFrom(toDay(next.from));
          range.setTo(toDay(next.to));
        }}
      />
      {metric.state === 'loading' && <p className="tpl-muted">Loading…</p>}
      {metric.state === 'empty' && <p className="tpl-muted">No data in this range.</p>}
      {metric.state === 'error' && <p className="tpl-muted">This metric could not be loaded.</p>}
      <ChartBar
        data={(metric.data?.rows ?? []).map((row) => ({ group: labelOf(row) || '(none)', value: valueOf(row) }))}
        xAxisKey="group"
        yAxisKeys={['value']}
        isLoading={metric.state === 'loading'}
        onSegmentClick={(point) => drill(String(point.group ?? ''))}
      />
      {metric.provenance && (
        <ProvenanceFooter metricName={METRIC_NAME} dataAsOf={metric.provenance.dataAsOf} sampleN={metric.provenance.sampleN} />
      )}
    </main>
  );
}

function readRows(payload: unknown): Row[] | null {
  return isRecord(payload) && Array.isArray(payload.rows) ? payload.rows.filter(isRecord) : null;
}

function Records() {
  const [group] = useQueryState('group', parseAsString);
  const records = useQuery(
    'knowledge_query_data',
    { tool: 'knowledge_advanced_query', params: { entity_type: ENTITY_TYPE, filter: { [GROUP_BY]: group ?? '' }, limit: 50 } },
    { parse: readRows, enabled: group !== null }
  );
  return (
    <main className="tpl-page">
      <Section title={group ?? 'Records'}>
        {records.state === 'loading' && <p className="tpl-muted">Loading…</p>}
        {records.state === 'empty' && <p className="tpl-muted">No records in this group.</p>}
        <ul className="tpl-list" aria-label={group ?? 'Records'}>
          {(records.data ?? []).map((record) => (
            <li key={String(record.id)} className="tpl-row">
              {String(record.name ?? record.id)}
            </li>
          ))}
        </ul>
      </Section>
    </main>
  );
}

function CurrentView() {
  const { routeInput } = useSurfaceApp();
  if (routeInput === null) return null;
  return routeInput.view === 'records' ? <Records /> : <Overview />;
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'analytics', version: '1.0.0' }}>
      <CurrentView />
    </SurfaceApp>
  );
}

